// Package test_vector provides a helper for running vectorized proto tests.
package test_vector

import (
	"encoding/base64"
	"testing"

	"google.golang.org/protobuf/encoding/prototext"
	"google.golang.org/protobuf/proto"
)

// Run takes a map of test case name -> base64(T), unmarshals them, and invokes
// `cb` inside a parallel `t.Run("<name>", ...)` subtest for each vector.
//
// Vector maps are generated by `build.py` from the 'testing/vectors'
// directory.
func Run[T proto.Message](t *testing.T, vectors map[string]string, cb func(t *testing.T, testCase T)) {
	t.Helper()

	if len(vectors) == 0 {
		t.Fatal("must supply at least one test vector")
	}

	for name, vector := range vectors {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			var zero T
			msg := zero.ProtoReflect().New().Interface().(T)
			dat, err := base64.StdEncoding.DecodeString(vector)
			if err != nil {
				t.Fatal(err)
			}
			if err := prototext.Unmarshal(dat, msg); err != nil {
				t.Fatal(err)
			}

			cb(t, msg)
		})
	}
}
